<script setup lang="ts">
const props=defineProps<{game:any}>(),emit=defineEmits(['open-contracts','changed','processing'])
const navigationNews=useNavigationNews()
const data=ref<any>(null),error=ref(''),loading=ref(false),detail=ref<any>(null),older=ref<any[]>([]),offset=ref(0)
const context=useState<Record<string,string>>('world-region',()=>({})),selected=computed({get:()=>context.value[props.game.id]||'karsen-0',set:(v:string)=>context.value={...context.value,[props.game.id]:v}})
const section=ref('regions'),locationOpen=ref(false)
function chooseRegion(id:string){selected.value=id;locationOpen.value=false}
const focus=useState<Record<string,string>>('world-event',()=>({}))
const region=computed(()=>data.value?.regions.find((r:any)=>r.id===selected.value)),country=computed(()=>data.value?.countries.find((c:any)=>c.id===region.value?.countryId))
const labels:any={stability:'Estabilidade',security:'Segurança',economy:'Economia',tension:'Tensão'},types:any={government:'Governo',corporation:'Corporação',armed_faction:'Facção',civil:'Organização civil',rival_pmc:'PMC rival'},status:any={active:'Em andamento',completed:'Encerrado',resolved:'Resolvido'}
const base=()=>'/api/v1/games/'+props.game.id+'/world'
async function refresh(){loading.value=true;error.value='';try{data.value=await $fetch(base());older.value=[];offset.value=0;detail.value=null;if(focus.value[props.game.id]){await cause(focus.value[props.game.id]);focus.value={...focus.value,[props.game.id]:''}};navigationNews.markRead(props.game.id,'world.'+section.value)}catch(e:any){error.value=e.data?.message||'Não foi possível carregar o mundo.'}finally{loading.value=false}}
async function history(){try{const rows=await $fetch<any[]>(base()+'/regions/'+selected.value+'/history?offset='+offset.value+'&limit=20');older.value.push(...rows);offset.value+=rows.length}catch{error.value='Não foi possível carregar o histórico.'}}
async function cause(id:string){section.value='news';try{detail.value=await $fetch(base()+'/events/'+id)}catch{error.value='Não foi possível carregar a origem.'}}
watch(selected,()=>{detail.value=null;older.value=[];offset.value=0})
watch(()=>[props.game.id,props.game.stateVersion],refresh)
onMounted(refresh)

watch(section,()=>{if(data.value&&!loading.value)navigationNews.markRead(props.game.id,'world.'+section.value)})
</script>
<template><div class="world-panel">
 <div class="section-intro"><h2>Asterra em movimento</h2><p>O mundo muda ao avançar os turnos. Indicadores e presença são estimativas, com fonte, confiança e data.</p></div>
 <div v-if="error" class="error" role="alert">{{error}} <button class="secondary" @click="refresh">Tentar novamente</button></div><p v-if="loading" role="status">Carregando dossiês…</p>
 <template v-if="data"><SectionNav :game-id="game.id" scope="world" v-model="section" label="Seções do mundo" :items="[['regions','Países e regiões'],['news','Acontecimentos'],['intelligence','Inteligência'],['rivals','PMCs rivais'],['organizations','Organizações']]" /><div v-show="['regions','news','intelligence'].includes(section)" class="world-layout"><div class="world-location"><button type="button" class="secondary location-toggle" :aria-expanded="locationOpen" aria-controls="world-location-options" @click="locationOpen=!locationOpen"><span><small>PAÍS E REGIÃO</small><strong>{{region?.name||'Selecionar região'}}</strong><small>{{country?.name}}</small></span><span>{{locationOpen?'Fechar ▴':'Trocar ▾'}}</span></button><div v-show="locationOpen" id="world-location-options" class="country-list"><div v-for="c in data.countries" :key="c.id" class="country-group"><button type="button" class="country-option" :class="{selected:country?.id===c.id}" :aria-pressed="country?.id===c.id" @click="selected=c.regions[0].id"><strong>{{c.name}}</strong><span class="selection-mark" aria-hidden="true">{{country?.id===c.id?'✓':''}}</span></button><div v-if="country?.id===c.id" class="world-regions" :aria-label="'Regiões de '+c.name"><button v-for="r in c.regions" :key="r.id" type="button" class="region-option" :class="{selected:selected===r.id}" :aria-pressed="selected===r.id" @click="chooseRegion(r.id)"><span class="region-name">{{r.name}}<small v-if="r.activeConflicts">Conflito ativo</small></span><span class="selection-mark" aria-hidden="true">{{selected===r.id?'✓':''}}</span></button></div></div></div></div>
 <section v-if="region" class="panel"><span class="eyebrow">DOSSIÊ REGIONAL · {{country?.name}}</span><h2>{{region.name}}</h2><p>Controle político informado: {{region.controllerName}}</p><p>{{region.source}} · confiança {{region.confidence}}% · coletado turno {{region.collectedTurn}} · atual turno {{game.currentTurn}}</p><div v-show="section==='regions'" class="world-indicators"><div v-for="(value,key) in region.indicators" :key="key"><span>{{labels[key]}}</span><strong>{{value.min}}–{{value.max}}</strong><small>estimativa / 100</small></div></div>
 <IntelligencePanel v-show="section==='intelligence'" :key="game.id+':'+region.id" :game="game" target-type="region" :target-id="region.id" @changed="emit('changed')" @processing="emit('processing',$event)" />
 <template v-if="section==='regions'"><h3>Presença estimada</h3><p v-for="p in region.presence" :key="p.organizationId">{{p.name}} <strong>≈ {{p.estimatedShare}}%</strong></p><p>Presença representa influência local e pode diferir do controle político.</p>
 <div v-for="c in data.conflicts.filter((c:any)=>c.regionId===selected)" :key="c.id" class="mission-report"><h3>Conflito · intensidade {{c.intensity.toLowerCase()}}</h3><p>Desde turno {{c.startedTurn}} · {{c.participants.map((p:any)=>p.name).join(' × ')}}</p><button class="secondary" @click="cause(c.causeId)">Consultar origem</button></div>
 <button class="primary" @click="emit('open-contracts',selected)">Ver contratos de {{region.name}} →</button>
 </template><template v-if="section==='news'"><h3>Notícias da região</h3><p v-if="!data.history.some((e:any)=>e.regionId===selected)&&!older.length">Nenhuma notícia recente. Consulte o histórico para eventos anteriores.</p>
 <article v-for="e in (older.length?older:data.history.filter((e:any)=>e.regionId===selected))" :key="e.id" class="mission-report"><span class="eyebrow">turno {{e.createdTurn}} · {{status[e.status]||e.status}}</span><p>{{e.summary}}</p><div class="personnel-actions"><button v-if="e.originId" class="secondary" @click="cause(e.originId)">Consultar causa</button><button v-if="e.contractId" class="secondary" @click="emit('open-contracts',selected)">Ver contratos relacionados</button></div></article>
 <button class="secondary" @click="history">{{offset?'Carregar mais notícias':'Consultar histórico regional'}}</button>
 <article v-if="detail" class="panel world-cause"><span class="eyebrow">ORIGEM · turno {{detail.createdTurn}}</span><p>{{detail.summary}}</p><button v-if="detail.originId" class="secondary" @click="cause(detail.originId)">Consultar causa anterior</button><button class="secondary" @click="detail=null">Fechar origem</button></article>
 </template></section></div>
 <template v-if="section==='rivals'"><section class="section-intro"><h2>PMCs rivais</h2><p>Rivais disputam ofertas disponíveis após quatro turnos de exposição. Contratos já aceitos pela companhia ficam protegidos.</p></section><div class="personnel-grid"><article v-for="r in data.rivals" :key="r.id" class="panel"><h3>{{r.name}}</h3><p>Reputação {{r.reputation}} / 100<br>{{r.activeJobs}} / {{r.capacity}} operações<br>{{r.completed}} concluídas · {{r.failed}} fracassadas<br>Condição financeira estimada: {{r.financialCondition}}</p></article></div>
 </template><template v-if="section==='organizations'"><section class="section-intro"><h2>Organizações e relações</h2></section><div class="personnel-grid"><article v-for="o in data.organizations" :key="o.id" class="panel"><span class="eyebrow">{{types[o.type]}}</span><h3>{{o.name}}</h3><p>Objetivo: {{o.goal}}<br>Relação com sua companhia: {{o.companyRelation}}</p><details><summary>Relações diplomáticas estimadas</summary><p v-for="r in o.relations" :key="r.organizationId">{{r.name}} · {{r.relationship}}</p></details></article></div>
 </template></template></div></template>
